package com.jamshed.hrms.controller;
import com.jamshed.hrms.dto.TimesheetRequest;import com.jamshed.hrms.entity.*;import com.jamshed.hrms.exception.*;import com.jamshed.hrms.repository.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/timesheets") public class TimesheetController{private final TimesheetRepository r;private final EmployeeRepository er;public TimesheetController(TimesheetRepository r,EmployeeRepository er){this.r=r;this.er=er;}@GetMapping public List<Timesheet> all(){return r.findAll();}@PostMapping public Timesheet create(@Valid @RequestBody TimesheetRequest d){Employee e=er.findById(d.employeeId()).orElseThrow(()->new ResourceNotFoundException("Employee not found"));return r.save(Timesheet.builder().employee(e).weekStart(d.weekStart()).hours(d.hours()).projectName(d.projectName()).notes(d.notes()).status("DRAFT").build());}@PatchMapping("/{id}/status") public Timesheet status(@PathVariable Long id,@RequestParam String value){Timesheet t=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Timesheet not found"));if(!List.of("DRAFT","SUBMITTED","APPROVED","REJECTED").contains(value))throw new BusinessException("Unsupported timesheet status");t.setStatus(value);return r.save(t);}}
